mkdir -p /tmp/scale && cat > /tmp/scale/gen1.mjs <<'EOF'
import { writeFileSync } from 'node:fs';
const cases = [];
const lens = [0,1,9,10,99,100,255,256,999,1000,4095,4096,65535,65536];
for (const n of lens) {
  cases.push({name:`a-len-${n}-x`, argv:['--a','x'.repeat(n),'--b','5']});
}
// varied alphabet, ASCII printable cycling 0x20..0x7e
const alpha = Array.from({length:0x7f-0x20},(_,i)=>String.fromCharCode(0x20+i)).join('');
function cyc(n){let s='';while(s.length<n)s+=alpha;return s.slice(0,n);}
for (const n of lens) {
  if (n===0) continue;
  cases.push({name:`a-len-${n}-cyc`, argv:['--a',cyc(n),'--b','-7']});
}
writeFileSync('/tmp/cases-scale-a.json', JSON.stringify(cases));
console.log(cases.length);
EOF
node /tmp/scale/gen1.mjs

cat > /tmp/scale/gen2.mjs <<'EOF'
import { writeFileSync } from 'node:fs';
const cases = [];
const digitCounts=[1,2,18,19,20,100,1000,10000];
function num(d){ if(d===1) return '7'; return '9'+'1234567890'.repeat(Math.ceil((d-1)/10)).slice(0,d-1); }
for(const d of digitCounts){
  const s=num(d);
  cases.push({name:`b-digits-${d}`,argv:['--a','hello','--b',s]});
  cases.push({name:`b-digits-${d}-neg`,argv:['--a','hello','--b','-'+s]});
  cases.push({name:`b-digits-${d}-zeros`,argv:['--a','hello','--b','0'.repeat(d-1)+'1']});
  cases.push({name:`b-digits-${d}-allzero`,argv:['--a','hello','--b','0'.repeat(d)]});
  cases.push({name:`b-digits-${d}-plus`,argv:['--a','hello','--b','+'+s]});
  cases.push({name:`b-digits-${d}-space`,argv:['--a','hello','--b','  '+s+'  ']});
  cases.push({name:`b-digits-${d}-us`,argv:['--a','hello','--b',s.replace(/(.{3})/g,'$1_').replace(/_$/,'')]});
}
// powers of two boundaries
for (const e of [7,8,15,16,31,32,62,63,64,127,128,255,256,511,512,1023,1024]){
  cases.push({name:`b-2^${e}`,argv:['--a','p','--b',(2n**BigInt(e)).toString()]});
  cases.push({name:`b-2^${e}-1`,argv:['--a','p','--b',(2n**BigInt(e)-1n).toString()]});
  cases.push({name:`b--2^${e}`,argv:['--a','p','--b',(-(2n**BigInt(e))).toString()]});
}
writeFileSync('/tmp/cases-scale-b.json', JSON.stringify(cases));
console.log(cases.length);
EOF
node /tmp/scale/gen2.mjs

cat > /tmp/scale/gen3.mjs <<'EOF'
import { writeFileSync } from 'node:fs';
const MAXARG = 131071;
const cases = [];
const push=(name,argv)=>cases.push({name,argv});
// near the OS single-arg limit
for (const n of [131067,131068,131069,131070,131071]) push(`a-max-${n}`,['--a','x'.repeat(n),'--b','5']);
// both maximal at once: a at max minus room, b at 4300 digits (python's limit)
push('both-max', ['--a','y'.repeat(MAXARG),'--b','9'.repeat(4300)]);
push('both-max-neg', ['--a','y'.repeat(MAXARG),'--b','-'+'9'.repeat(4300)]);
push('both-max-b4299', ['--a','z'.repeat(MAXARG),'--b','1'.repeat(4299)]);
// total argv near limit but split across a and b
push('a-127k-b-4300', ['--a','q'.repeat(127000),'--b','7'.repeat(4300)]);
// escape-heavy repr at scale
push('a-backslash-65536', ['--a','\\'.repeat(65536),'--b','1']);
push('a-singlequote-65536', ['--a',"'".repeat(65536),'--b','1']);
push('a-dquote-65536', ['--a','"'.repeat(65536),'--b','1']);
push('a-mixquote-65536', ['--a',"'\"".repeat(32768),'--b','1']);
push('a-tab-65536', ['--a','\t'.repeat(65536),'--b','1']);
push('a-newline-65536', ['--a','\n'.repeat(65536),'--b','1']);
push('a-cr-65536', ['--a','\r'.repeat(65536),'--b','1']);
push('a-del-65536', ['--a','\x7f'.repeat(65536),'--b','1']);
push('a-bell-65536', ['--a','\x07'.repeat(65536),'--b','1']);
push('a-esc-65536', ['--a','\x1b'.repeat(65536),'--b','1']);
push('a-space-65536', ['--a',' '.repeat(65536),'--b','1']);
push('a-max-backslash', ['--a','\\'.repeat(MAXARG),'--b','1']);
push('a-max-newline', ['--a','\n'.repeat(MAXARG),'--b','1']);
push('a-max-del', ['--a','\x7f'.repeat(MAXARG),'--b','1']);
// non-ascii far into a long string -> UnicodeEncodeError with big position
for (const n of [255,4095,65535]) {
  push(`a-nonascii-at-${n}`, ['--a','a'.repeat(n)+'é'+'b'.repeat(10),'--b','1']);
}
push('a-nonascii-at-end-max', ['--a','a'.repeat(MAXARG-2)+'é','--b','1']);
// long value that looks like an option
push('a-dashdash-long', ['--a','-'.repeat(1000),'--b','1']);
push('a-eq-long', ['--a='+'w'.repeat(100000),'--b','1']);
writeFileSync('/tmp/cases-scale-max.json', JSON.stringify(cases));
console.log(cases.length);
EOF
node /tmp/scale/gen3.mjs && cd /tmp && timeout 900 node /tmp/harness/diff.mjs --file /tmp/cases-scale-max.json 2>&1 | grep -E '^(FAIL|SKIP)|matched'
